INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP016', 'Baskets ASICS Unisex GEL-CUMULUS 16 Cream', ' ASICS', 'Cette sneaker élégante d''ASICS allie un design intemporel à des technologies avancées pour un confort optimal lors des longues distances. La tige en mesh respirant assure une excellente ventilation et garde les pieds frais, tandis que la semelle intermédiaire FluidRide et l''amorti double GEL absorbent les chocs sans effort. La semelle extérieure AHAR, durable, garantit une adhérence fiable, même en cas d''utilisation intensive. Grâce à son poids léger et au système innovant Trusstic, l''efficacité de la foulée est améliorée. La semelle intérieure amovible et anti-odeurs augmente le confort de port. Parfait pour ceux qui recherchent une combinaison de performance, de durabilité et de style, avec une élégante palette de couleurs crème/ivoire', '150', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42", "42,5", "43,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_cumulus_16_creamivory_6.jpg', '16', 'Unisexe', '[''blanc'']'),
('KVP017', 'Baskets ASICS Unisexe GEL-CUMULUS 16 White', ' ASICS', 'Découvrez l''alliance parfaite entre performance et élégance avec ces baskets signées ASICS. Conçues pour offrir un confort exceptionnel sur de longues distances, elles séduisent grâce à leur design intemporel et à leur technologie avancée. Leur tige en mesh et en synthétique assure une excellente ventilation, maintenant vos pieds frais même lors d''efforts prolongés. La semelle intermédiaire FluidRide procure une sensation de légèreté et d''amorti dynamique, tandis que la technologie GEL intégrée à l''avant-pied et au talon absorbe efficacement les chocs pour une foulée tout en douceur. La semelle extérieure en caoutchouc AHAR garantit une durabilité remarquable et une adhérence optimale sur toutes les surfaces. Grâce au Trusstic System et à la Guidance Line, chaque pas devient plus stable et plus efficace. La semelle intérieure ComforDry, amovible et anti-odeur, renforce le confort au quotidien. Convient à tous, ce modèle est idéal aussi bien pour la pratique sportive que pour un usage quotidien. Optez pour la qualité et l''innovation de la marque japonaise ASICS et élevez votre expérience de marche ou de course à un niveau supérieur.', '150', '["35,5", "36", "37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_cumulus_16_whiteironclad_7.jpg', '4', 'Unisexe', '[''blanc'']'),
('KVP018', 'Baskets ASICS Unisexe GEL-CUMULUS 16 Cream', ' ASICS', 'Découvrez l''alliance parfaite entre technologie avancée et élégance sportive avec ces baskets signées ASICS. Conçues pour les amateurs de confort et de performance, elles se distinguent par leur design moderne et leur couleur Cream/Clay Grey, idéale pour un look raffiné au quotidien. Leur tige en mesh et synthétique assure une excellente aération, gardant vos pieds frais même lors d''efforts prolongés. La semelle intermédiaire FluidRide offre une légèreté remarquable tout en garantissant un amorti dynamique et réactif, tandis que la technologie GEL intégrée à l''avant-pied et au talon absorbe efficacement les chocs, pour une sensation de douceur à chaque pas. Grâce à la semelle extérieure en caoutchouc AHAR, la durabilité et l''adhérence sont au rendez-vous, même sur les surfaces les plus exigeantes. Le système Trusstic et la Guidance Line optimisent la stabilité et la fluidité du mouvement, renforçant l''efficacité de votre foulée. La semelle intérieure ComforDry, amovible et anti-odeur, contribue à maintenir un environnement sain et sec. Convient à tous, ce modèle léger est un choix incontournable pour ceux qui recherchent la qualité, la fonctionnalité et le style, que ce soit pour la course à pied ou pour un usage quotidien. Faites confiance à la marque ASICS, référence mondiale en matière de baskets innovantes, pour accompagner chaque pas vers vos objectifs.', '150', '["35,5", "36", "37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_cumulus_16_creamclay_grey_6.jpg', '23', 'Unisexe', '[''gris'', ''marron'', ''blanc'']'),
('KVP019', 'Baskets ASICS Unisexe GEL-KAYANO 12.1 Cream', ' ASICS', 'Découvrez un confort et un style ultimes avec cette sneaker exclusive, fruit d''une collaboration unique entre ASICS et KITH. Inspirée d''un modèle emblématique de 2006, cette version associe une tige en mesh respirant à des empiècements synthétiques pour un look moderne. Grâce à la technologie avancée FLUIDRIDE et à l''amorti GEL à l''avant-pied comme à l''arrière-pied, chaque pas est à la fois facile et confortable. La construction de la semelle, basée sur la GEL-NIMBUS 17, offre un soutien optimal et une grande durabilité. La semelle intérieure recyclée souligne le caractère durable du modèle. Parfaite pour ceux qui recherchent une sneaker polyvalente et élégante, alliant sans effort performance sportive et mode', '180', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42", "42,5", "43,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_kayano_121_creampure_silver_6.jpg', '11', 'Unisexe', '[''argent'', ''blanc'']'),
('KVP020', 'Baskets ASICS Unisexe GEL-KAYANO 12.1 White', ' ASICS', 'Cette sneaker allie élégance sportive et technologie innovante, fruit d''une collaboration unique avec KITH. Inspiré par les armures gothiques européennes de 2006, le modèle incarne à la fois l''héritage et une touche de modernité. Grâce à sa tige en mesh respirant et en matières synthétiques, le confort reste optimal, tandis que la technologie FLUIDRIDE et le système d''amorti GEL à l''avant et à l''arrière du pied offrent une excellente absorption des chocs et un soutien léger. La doublure intérieure écologique souligne son caractère durable. Ce modèle unisexe propose l''équilibre parfait entre style, performance et confort, idéal pour ceux qui recherchent une sneaker lifestyle exclusive et fonctionnelle', '180', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42", "42,5", "43,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_kayano_121_whitepure_silver_6.jpg', '4', 'Unisexe', '[''argent'', ''blanc'']'),
('KVP021', 'Baskets ASICS Femme GEL-NUNOBIKI Cosmos', ' ASICS', 'Découvrez une nouvelle dimension du style sportif avec ces baskets pour femmes signées ASICS. Inspirées par l''univers des trailrunners du début des années 2000, elles se distinguent par une silhouette moderne et dynamique, idéale pour les passionnées de mode urbaine à la recherche de performance. La tige en matériau synthétique associe habilement des finitions mates et semi-brillantes, créant un contraste raffiné dans une élégante couleur Cosmos/Pure Silver. Les larges lacets en ruban apportent une touche originale et tendance, tout en assurant un maintien optimal. La semelle extérieure, spécialement conçue pour le trail, offre une adhérence supérieure sur différents types de surfaces, garantissant sécurité et stabilité à chaque pas. Grâce à la technologie GEL intégrée au niveau du talon, l''amorti est exceptionnel, absorbant efficacement les chocs pour un confort durable même lors d''une utilisation prolongée. Parfaitement adaptées aux femmes actives qui souhaitent allier fonctionnalité, innovation et esthétique contemporaine, ces baskets incarnent l''équilibre parfait entre la mode et la performance, fidèles à l''esprit d''excellence de la marque japonaise ASICS. Offrez-vous une expérience unique où chaque détail est pensé pour sublimer votre quotidien, que ce soit en ville ou sur les sentiers.', '120', '["35,5", "36", "37", "37,5", "38", "39", "39,5", "40", "40,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_women_gel_nunobiki_cosmospure_silver_6.jpg', '16', 'Femme', '[''argent'']'),
('KVP022', 'Baskets ASICS Femme GEL-NUNOBIKI White', ' ASICS', 'Découvrez l''alliance parfaite entre le style contemporain et la performance avec ces baskets signées par la marque japonaise ASICS. Inspirées par les célèbres chutes de Nunobiki à Kobe, ces chaussures affichent une silhouette raffinée qui rappelle les modèles de trail emblématiques du début des années 2000. Leur dessus en matière synthétique se distingue par une combinaison élégante de couches mates et semi-brillantes, offrant un contraste subtil et moderne. Les larges lacets apportent une touche audacieuse, tandis que la semelle extérieure à motif trail assure une adhérence optimale, idéale pour affronter aussi bien les rues urbaines que les sentiers en pleine nature. Grâce à la technologie GEL placée au niveau du talon, chaque pas bénéficie d''une excellente absorption des chocs, garantissant un confort exceptionnel tout au long de la journée. La semelle intérieure durable, conçue selon un procédé de teinture respectueux de l''environnement, souligne l''engagement de la marque envers la durabilité. Polyvalentes et élégantes, ces baskets conviennent parfaitement aux femmes à la recherche de chaussures alliant confort, fonctionnalité et esthétique pour un usage quotidien ou sportif. Adoptez l''excellence ASICS et vivez une expérience unique où mode et innovation se rencontrent.', '120', '["35,5", "36", "37", "37,5", "38", "39", "39,5", "40", "40,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_women_gel_nunobiki_whitepure_silver_6.jpg', '17', 'Femme', '[''argent'', ''blanc'']'),
('KVP023', 'Baskets ASICS Femme GEL-QUANTUM 360 I Graphite Grey', ' ASICS', 'Entrez dans un monde de confort et d''innovation avec cette sneaker élégante d''ASICS. L''empeigne en mesh respirant assure une ventilation optimale, tandis que les détails en impression 5D apportent une touche moderne. Grâce à la technologie avancée TRUSSTIC et au contrefort de talon externe en TPU, une stabilité et un soutien supplémentaires sont assurés à chaque pas. La technologie unique DIVISION GEL et l''amorti FF BLAST ECO, enrichi de 20% de biomasse provenant de la canne à sucre, offrent une excellente absorption des chocs et un grand confort. Conçue en collaboration avec l''ASICS Institute of Sport Science, cette sneaker combine performances sportives et design contemporain. Idéal pour celles et ceux qui souhaitent allier style et fonctionnalité', '180', '["36", "37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42", "42,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_women_gel_quantum_360_i_graphite_greyhazard_green_6.jpg', '17', 'Femme', '[''gris'', ''vert'']'),
('KVP024', 'Baskets Adidas Bébé Superstar Led Lights Comfort Closure Elastic Lace Cloud White', ' Adidas', 'Découvrez l''alliance parfaite entre innovation et style avec cette paire de baskets signée Adidas, conçue spécialement pour les tout-petits. Arborant la célèbre silhouette intemporelle, ce modèle séduit par ses trois bandes emblématiques illuminées par des LED intégrées, offrant divers effets lumineux qui captiveront l''attention à chaque pas. Grâce à une commande discrète sur le côté, votre enfant peut facilement activer ou changer les effets lumineux, ajoutant ainsi une touche ludique à ses tenues quotidiennes. La matière synthétique du dessus assure robustesse et facilité d''entretien, tandis que la doublure textile garantit douceur et confort optimal. La semelle extérieure en caoutchouc, dotée d''une cupsole, offre une adhérence fiable pour accompagner les premiers pas en toute sécurité. L''ajustement est simplifié grâce à des lacets élastiques et à une fermeture à scratch, permettant un enfilage rapide et un maintien sûr. La semelle intérieure OrthoLite assure un amorti supplémentaire, et la semelle de mesure Adifit permet de vérifier la taille idéale pour un confort sur mesure. Parfaites pour les jeunes explorateurs désireux de se démarquer, ces baskets associent l''héritage de la marque Adidas à une technologie moderne, pour un look tendance et fonctionnel. Offrez à votre enfant le plaisir de marcher avec style, confort et sécurité, tout en profitant de la qualité reconnue d''Adidas.', '75', '["21", "22", "23", "23,5", "24", "25"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_infant_superstar_led_lights_comfort_closure_elastic_lace_cloud_white_core_black_cloud_white_11.jpg', '4', 'Unisexe', '[''noir'', ''blanc'']'),
('KVP025', 'Baskets Adidas Enfant Superstar Led Lights CF EL Cloud White', ' Adidas', 'Découvrez une paire de baskets qui allie à la perfection héritage sportif et innovation moderne. Inspirée des modèles emblématiques des années 70, cette création signée Adidas séduit par son look rétro revisité et ses détails ludiques. La matière synthétique de haute qualité assure une durabilité remarquable, tandis que la doublure textile procure un confort optimal au quotidien. La célèbre shell-toe et le logo Trefoil sur le talon renforcent le caractère authentique de cette chaussure, idéale pour les jeunes amateurs de style. Ce qui distingue particulièrement ce modèle, ce sont les effets lumineux LED intégrés dans les trois bandes iconiques. Trois modes d''éclairage différents, activables simplement grâce à un bouton, apportent une touche de fantaisie et garantissent de ne jamais passer inaperçu sur le terrain de jeu ou à l''école. La semelle cup en caoutchouc offre une adhérence fiable, essentielle pour accompagner les enfants dans toutes leurs activités. Avec sa fermeture à lacets, cette basket assure un maintien parfait du pied. Opter pour ce modèle, c''est offrir à son enfant une combinaison unique de style intemporel, de confort et d''innovation, signée par la marque de référence Adidas. Parfait pour celles et ceux qui souhaitent exprimer leur personnalité tout en profitant d''une chaussure résistante et tendance. Convient aux enfants.', '80', '["30,5", "29", "30", "31", "31,5", "32"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_kids_superstar_led_lights_cf_el_cloud_white_core_black_cloud_white_10.jpg', '12', 'Enfant', '[''noir'', ''blanc'']');